// @pit: {"label": "Bump version to 0.38.0 in package files, README pin, and CHANGELOG heading"}
async ({ workspace: { batch, search } }) => {
  const links = await search("[Unreleased]:", { path: "CHANGELOG.md" });
  const r = await batch([
    { kind: "edit", file: "CHANGELOG.md", changes: { revision: "gDPCyUVgWG7w", changes: [
      { kind: "insertAfter", anchor: "6:47DEQ", content: "## [0.38.0] - 2026-11-17\n" },
    ] } },
    { kind: "edit", file: "package.json", changes: { revision: "93NOxE2jbktS", changes: [
      { kind: "replace", start: "3:GQdGi", content: '  "version": "0.38.0",' },
    ] } },
    { kind: "edit", file: "package-lock.json", changes: { revision: "HP8e8NA0yaKv", changes: [
      { kind: "replace", start: "3:GQdGi", content: '  "version": "0.38.0",' },
      { kind: "replace", start: "9:gfMs8", content: '      "version": "0.38.0",' },
    ] } },
    { kind: "edit", file: "README.md", changes: { revision: "oqAAGI66Euu-", changes: [
      { kind: "replace", start: "53:VaLQJ", content: "Run `/reload` after updating. Prefer a fixed release? Use `pi install git:github.com/cv/pit@v0.38.0` instead; package updates won't move a pinned install." },
    ] } },
  ]);
  return { links: links.matches.length, r: r.results.map((x: any) => x.ok) };
}
